SELECT COUNT(*) current_paragraphs,SUM(slot=0) zero_slot,SUM(has_ref) referenced_today,SUM(has_ref AND referenced=written) born_with_reference,SUM(has_ref AND referenced>written) gained_reference,SUM(NOT has_ref) no_reference_today,SUM(NOT has_ref AND referenced IS NULL) never_referenced,SUM(NOT has_ref AND referenced IS NOT NULL) reference_removed,SUM(NOT has_ref AND written<='2021-10-01') unsourced_5_years,SUM(NOT has_ref AND written<='2016-10-01') unsourced_10_years,SUM(NOT has_ref AND written<='2011-10-01') unsourced_15_years FROM facts;
